select jsonb_pretty(jsonb_build_object(
 'migrations', (select jsonb_build_object('n',count(*),'max',max(version)) from supabase_migrations.schema_migrations),
 'rows', jsonb_build_object(
   'events',(select count(*) from public.events),
   'event_ticket_types',(select count(*) from public.event_ticket_types),
   'event_ticket_orders',(select count(*) from public.event_ticket_orders),
   'event_tickets',(select count(*) from public.event_tickets),
   'event_checkins',(select count(*) from public.event_checkins),
   'regular_activities',(select count(*) from public.regular_activities),
   'activity_schedule_rules',(select count(*) from public.activity_schedule_rules),
   'activity_exceptions',(select count(*) from public.activity_exceptions),
   'activity_follows',(select count(*) from public.activity_follows),
   'notification_log',(select count(*) from public.notification_log),
   'admin_config',(select count(*) from public.admin_config),
   'profiles',(select count(*) from public.profiles)),
 'events_data_md5',(select md5(string_agg(row(id,title,description,category,venue,locality,lat,lng,starts_at,ends_at,status,is_hidden,organiser_user_id,organiser_business_id,organiser_hub_id,is_platform_event,has_tickets,tickets_sold,cover_url,ticket_url,hub_visibility,calendar_approved)::text,'|' order by id)) from public.events),
 'ticketing_data_md5',(select md5(coalesce((select string_agg(t::text,'|' order by t.id) from public.event_ticket_types t),'')||coalesce((select string_agg(o::text,'|' order by o.id) from public.event_ticket_orders o),'')||coalesce((select string_agg(k::text,'|' order by k.id) from public.event_tickets k),''))),
 'activities_data_md5',(select md5(coalesce((select string_agg(a::text,'|' order by a.id) from public.regular_activities a),'')||coalesce((select string_agg(r::text,'|' order by r.id) from public.activity_schedule_rules r),'')||coalesce((select string_agg(x::text,'|' order by x.id) from public.activity_exceptions x),''))),
 'catalog', jsonb_build_object(
   'public_tables',(select count(*) from pg_tables where schemaname='public'),
   'public_functions',(select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'),
   'functions_md5',(select md5(string_agg(pg_get_functiondef(p.oid), '' order by p.oid::regprocedure::text)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind in ('f','p')),
   'events_columns',(select string_agg(attname||':'||format_type(atttypid,atttypmod),',' order by attnum) from pg_attribute where attrelid='public.events'::regclass and attnum>0 and not attisdropped),
   'events_constraints',(select string_agg(conname,',' order by conname) from pg_constraint where conrelid='public.events'::regclass),
   'events_indexes',(select string_agg(indexname,',' order by indexname) from pg_indexes where schemaname='public' and tablename='events'),
   'events_triggers',(select string_agg(tgname,',' order by tgname) from pg_trigger where tgrelid='public.events'::regclass and not tgisinternal),
   'events_policies',(select string_agg(policyname,',' order by policyname) from pg_policies where schemaname='public' and tablename='events'),
   'ticket_types_triggers',(select string_agg(tgname,',' order by tgname) from pg_trigger where tgrelid='public.event_ticket_types'::regclass and not tgisinternal),
   'policies_total',(select count(*) from pg_policies where schemaname='public'),
   'triggers_total',(select count(*) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal),
   'new_objects_present',(select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('event_occurrences','event_submissions','event_change_requests','event_change_log','event_organiser_trust')),
   'reserve_def_md5',(select md5(pg_get_functiondef('public.reserve_ticket_basket(uuid,uuid,jsonb,integer,integer,jsonb,text)'::regprocedure)))),
 'fetch', (select jsonb_build_object('operations',(select value from public.admin_config where key='fetch.operations'))),
 'open_txns', (select count(*) from pg_stat_activity where state like 'idle in transaction%' and pid<>pg_backend_pid()),
 'blocked_now', (select count(*) from pg_stat_activity where wait_event_type='Lock')
))
